#pragma once

#include "BiquadFilter.h"
#include <cmath>
#include <algorithm>

namespace dsp {

/**
 * DI Output Conditioning:
 * 1. Asymmetrical transformer saturation: tanh(drive * x + 0.12 * (drive * x)^2)
 *    with a 15 Hz 1st-order DC blocker to strip static DC offset generated by the x^2 term.
 * 2. Fast FET-style feed-forward compressor: 4:1 ratio, 5 ms attack, 40 ms release.
 */
class FETCompressor {
public:
    FETCompressor() = default;

    void prepare(double sampleRate) noexcept {
        sampleRate_ = (sampleRate > 0.0) ? sampleRate : 48000.0;

        // 5 ms attack, 40 ms release as required by the DI Output Conditioning spec
        attackCoeff_  = computeOnePoleCoeff(5.0f, sampleRate_);
        releaseCoeff_ = computeOnePoleCoeff(40.0f, sampleRate_);

        // 15 Hz 1st-order HPF to remove any DC shift introduced by 0.12 * (drive * x)^2
        dcBlocker_.setFirstOrderHighPass(sampleRate_, 15.0f);

        reset();
    }

    void reset() noexcept {
        envDb_ = -96.0f;
        dcBlocker_.reset();
    }

    /**
     * Transparent studio DI transformer waveshaper:
     * Gentle saturation with even-order warmth, scaled softly for clean headroom.
     */
    inline float saturateSample(float x, float drive) noexcept {
        const float d = std::clamp(drive, 0.5f, 4.0f);
        const float k = 0.45f * d;
        const float dx = k * x;
        const float shaped = std::tanh(dx + 0.02f * (dx * dx)) / k;
        return dcBlocker_.processSample(shaped);
    }

    /**
     * Fast FET-style 4:1 feed-forward compressor (5 ms attack, 40 ms release).
     */
    inline float compressSample(float x) noexcept {
        const float absX = std::abs(x);
        const float inputDb = 20.0f * std::log10(absX + 1.0e-7f);

        // Ballistic envelope follower in dB domain (5 ms attack, 40 ms release)
        const float coeff = (inputDb > envDb_) ? attackCoeff_ : releaseCoeff_;
        envDb_ = coeff * envDb_ + (1.0f - coeff) * inputDb;

        // 4:1 compression ratio above threshold (-16 dBFS) with 4 dB soft knee
        constexpr float kThresholdDb = -16.0f;
        constexpr float kRatio = 4.0f;
        constexpr float kSlope = 1.0f - (1.0f / kRatio); // 0.75 for 4:1
        constexpr float kKneeWidthDb = 4.0f;
        // Fade out +1.2 dB makeup below -42 dBFS so quiet guitar noise floor is not boosted
        const float makeupGate = std::clamp((envDb_ + 48.0f) / 12.0f, 0.0f, 1.0f);
        const float makeupDb = 1.2f * makeupGate;

        float overshootDb = envDb_ - kThresholdDb;
        float gainReductionDb = 0.0f;

        if (overshootDb <= -0.5f * kKneeWidthDb) {
            gainReductionDb = 0.0f;
        } else if (overshootDb >= 0.5f * kKneeWidthDb) {
            gainReductionDb = -kSlope * overshootDb;
        } else {
            const float kneeVal = overshootDb + 0.5f * kKneeWidthDb;
            gainReductionDb = -kSlope * (kneeVal * kneeVal) / (2.0f * kKneeWidthDb);
        }

        const float totalGainLinear = dbToLinear(gainReductionDb + makeupDb);
        return x * totalGainLinear;
    }

    inline float processSample(float x, float drive) noexcept {
        const float saturated = saturateSample(x, drive);
        return compressSample(saturated);
    }

private:
    static float computeOnePoleCoeff(float timeMs, double sampleRate) noexcept {
        if (timeMs <= 0.0f || sampleRate <= 0.0) return 0.0f;
        const float tauSamples = (timeMs * 0.001f) * static_cast<float>(sampleRate);
        return std::exp(-1.0f / std::max(tauSamples, 1.0f));
    }

    static inline float dbToLinear(float db) noexcept {
        return std::pow(10.0f, db * 0.05f);
    }

    double sampleRate_ = 48000.0;
    float attackCoeff_ = 0.0f;
    float releaseCoeff_ = 0.0f;
    float envDb_ = -96.0f;

    BiquadFilter dcBlocker_;
};

} // namespace dsp
